    const dataLines = lines.slice(2);

    const result = [];
    for (const line of dataLines) {
        const cells = parseRow(line);
        const obj = {};
        for (let i = 0; i < headers.length; i++) {
            const header = headers[i];
            const rawVal = cells[i] !== undefined ? cells[i] : '';
            obj[header] = parseValue(rawVal);
        }
        result.push(obj);
    }

    return result;
