function parseRow(line) {
    // Replace escaped pipes to avoid splitting on them
    const safeLine = line.replace(/\\\|/g, '__ESCAPED_PIPE__');
    const parts = safeLine.split('|');

    let startIndex = 0;
    let endIndex = parts.length;

    if (line.startsWith('|')) {
        startIndex = 1;
    }
    if (line.endsWith('|')) {
        endIndex = parts.length - 1;
    }

    const cells = [];
    for (let i = startIndex; i < endIndex; i++) {
        cells.push(parts[i].replace(/__ESCAPED_PIPE__/g, '|').trim());
    }
    return cells;
}

function parseValue(val) {
    const lower = val.toLowerCase();
    if (lower === 'true') return true;
    if (lower === 'false') return false;

    if (val !== '' && !isNaN(Number(val))) {
        return Number(val);
    }
    return val;
}

export default async function execute(args) {
  const { markdown } = args;

  // Split into lines and filter out empty ones
  const lines = markdown.trim().split('\n').map(l => l.trim()).filter(Boolean);

  if (lines.length < 2) {
    return [];
  }

  // Helper to split a row by unescaped pipes
  function parseRow(line) {
    // Remove leading and trailing pipes if present
    let content = line;
    if (content.startsWith('|')) content = content.slice(1);
    if (content.endsWith('|')) content = content.slice(0, -1);

    const cells = [];
    let currentCell = '';
    let escaped = false;

    for (let i = 0; i < content.length; i++) {
      const char = content[i];
      if (escaped) {
        currentCell += char;
        escaped = false;
      } else if (char === '\\') {
        // Check if next char is a pipe
        if (i + 1 < content.length && content[i + 1] === '|') {
          escaped = true;
        } else {
          currentCell += char;
        }
      } else if (char === '|') {
        cells.push(currentCell.trim());
        currentCell = '';
      } else {
        currentCell += char;
      }
    }
    cells.push(currentCell.trim());
    return cells;
  }

  // Parse header
  const headers = parseRow(lines[0]);

  // Skip delimiter line (lines[1])
  const dataLines = lines.slice(2);

  function parseValue(val) {
    if (val === 'true') return true;
    if (val === 'false') return false;

    // Check if it's a number
    if (val !== '' && !isNaN(Number(val))) {
      return Number(val);
    }

    return val;
  }

  const result = [];
  for (const line of dataLines) {
    const rawCells = parseRow(line);
    const obj = {};
    for (let i = 0; i < headers.length; i++) {
      const key = headers[i];
      const rawVal = rawCells[i] !== undefined ? rawCells[i] : '';
      obj[key] = parseValue(rawVal);
    }
    result.push(obj);
  }

  return result;
}

export default async function execute(args) {
  const markdown = args.markdown;
  if (!markdown || typeof markdown !== 'string') {
    return [];
  }

  const lines = markdown.trim().split('\n');
  let headers = [];
  const rows = [];
  let isHeader = true;

  for (let line of lines) {
    line = line.trim();
    if (!line.startsWith('|')) {
      continue;
    }

    // Check if the line is a markdown table separator (e.g., | :--- | :---: |)
    const isSeparator = /^\|?(\s*:?-+:?\s*\|)+$/.test(line);
    if (isSeparator) {
      isHeader = false;
      continue;
    }

    // Mask escaped pipes so they don't break the column split
    const maskedLine = line.replace(/\\\|/g, '__ESCAPED_PIPE__');

    // Split by pipe and clean up leading/trailing empty elements from outer pipes
    let cells = maskedLine.split('|').map(p => p.trim());
    if (cells.length > 0 && cells[0] === '') cells.shift();
    if (cells.length > 0 && cells[cells.length - 1] === '') cells.pop();

    if (isHeader && headers.length === 0) {
      headers = cells;
    } else {
      const obj = {};
      for (let i = 0; i < headers.length; i++) {
        let val = cells[i] !== undefined ? cells[i] : '';

        // Restore escaped pipes
        val = val.replace(/__ESCAPED_PIPE__/g, '|');

        // Type coercion
        if (val === 'true') {
          obj[headers[i]] = true;
        } else if (val === 'false') {
          obj[headers[i]] = false;
        } else if (val !== '' && !isNaN(Number(val))) {
          obj[headers[i]] = Number(val);
        } else {
          obj[headers[i]] = val;
        }
      }
      rows.push(obj);
    }
  }

  return rows;
}

