/**
 * Computes the optimal Levenshtein edit distance and operation alignment script
 * transforming the source DNA string into the target DNA string.
 * 
 * @param {Object} args - Task input containing source and target strings.
 * @param {string} args.source - The source DNA string.
 * @param {string} args.target - The target DNA string.
 * @returns {Promise<Object>} - An object with `editDistance` and `alignment` script.
 */
export default async function execute(args) {
    const { source, target } = args;

    const m = source.length;
    const n = target.length;

    // dp[i][j] stores the edit distance between source[0...i-1] and target[0...j-1]
    const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));

    for (let i = 0; i <= m; i++) {
        dp[i][0] = i;
    }
    for (let j = 0; j <= n; j++) {
        dp[0][j] = j;
    }

    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            if (source[i - 1] === target[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = 1 + Math.min(
                    dp[i - 1][j],     // deletion
                    dp[i][j - 1],     // insertion
                    dp[i - 1][j - 1]  // substitution
                );
            }
        }
    }

    const editDistance = dp[m][n];

    // Backtrack to find the optimal alignment script
    let i = m;
    let j = n;
    const reverseAlignment = [];

    while (i > 0 || j > 0) {
        if (i > 0 && j > 0 && source[i - 1] === target[j - 1] && dp[i][j] === dp[i - 1][j - 1]) {
            reverseAlignment.push({
                operation: 'keep',
                sourceChar: source[i - 1],
                targetChar: target[j - 1],
                sourceIndex: i - 1,
                targetIndex: j - 1
            });
            i--;
            j--;
        } else {
            let substituted = false;
            if (i > 0 && j > 0 && dp[i][j] === dp[i - 1][j - 1] + 1) {
                reverseAlignment.push({
                    operation: 'substitute',
                    sourceChar: source[i - 1],
                    targetChar: target[j - 1],
                    sourceIndex: i - 1,
                    targetIndex: j - 1
                });
                i--;
                j--;
                substituted = true;
            }

            if (!substituted) {
                if (i > 0 && dp[i][j] === dp[i - 1][j] + 1) {
                    reverseAlignment.push({
                        operation: 'delete',
                        sourceChar: source[i - 1],
                        targetChar: null,
                        sourceIndex: i - 1,
                        targetIndex: null
                    });
                    i--;
                } else if (j > 0 && dp[i][j] === dp[i][j - 1] + 1) {
                    reverseAlignment.push({
                        operation: 'insert',
                        sourceChar: null,
                        targetChar: target[j - 1],
                        sourceIndex: null,
                        targetIndex: j - 1
                    });
                    j--;
                }
            }
        }
    }

    const alignment = reverseAlignment.reverse();

    return {
        editDistance,
        alignment
    };
}

