      let minVal = dp[i][j];
      let subVal = (i > 0 && j > 0) ? dp[i - 1][j - 1] : Infinity;
      let delVal = i > 0 ? dp[i - 1][j] : Infinity;
      let insVal = j > 0 ? dp[i][j - 1] : Infinity;

      const minOp = Math.min(subVal, delVal, insVal);

