/**
 * Computes the optimal Levenshtein edit distance and edit operations script
 * transforming source into target.
 * 
 * Input args: { source: string, target: string }
 * Output JSON: { editDistance: number, operations: Array<{ op: string, char?: string }> }
 */
export default async function execute(args) {
  const source = args.source;
  const target = args.target;

  const m = source.length;
  const n = target.length;

  // Create DP matrix
  const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

  for (let i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (source[i - 1] === target[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        dp[i][j] = 1 + Math.min(
          dp[i - 1][j],    // deletion
          dp[i][j - 1],    // insertion
          dp[i - 1][j - 1] // substitution
        );
      }
    }
  }

  const editDistance = dp[m][n];

  // Backtrack to find operations
  let i = m;
  let j = n;
  const revOps = [];

  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && source[i - 1] === target[j - 1]) {
      // Check if this came from diagonal with no cost
      if (dp[i][j] === dp[i - 1][j - 1]) {
        revOps.push({ op: "keep", char: target[j - 1] });
        i--;
        j--;
        continue;
      }
    }

    let substitutions = [];
    if (i > 0 && j > 0) {
      substitutions.push({ val: dp[i - 1][j - 1], op: "substitute", i: i - 1, j: j - 1 });
    }
    let deletions = [];
    if (i > 0) {
      deletions.push({ val: dp[i - 1][j], op: "delete", i: i - 1, j: j });
    }
    let insertions = [];
    if (j > 0) {
      insertions.push({ val: dp[i][j - 1], op: "insert", i: i, j: j - 1 });
    }

    const currentVal = dp[i][j];

    // Find which transition led here
    let matched = false;

    // Priority: substitute/keep, delete, insert (standard backtracking order)
    if (i > 0 && j > 0 && dp[i - 1][j - 1] + (source[i - 1] === target[j - 1] ? 0 : 1) === currentVal) {
      if (source[i - 1] === target[j - 1]) {
        revOps.push({ op: "keep", char: target[j - 1] });
      } else {
        revOps.push({ op: "substitute", char: target[j - 1] });
      }
      i--;
      j--;
    } else if (i > 0 && dp[i - 1][j] + 1 === currentVal) {
      revOps.push({ op: "delete" });
      i--;
    } else if (j > 0 && dp[i][j - 1] + 1 === currentVal) {
      revOps.push({ op: "insert", char: target[j - 1] });
      j--;
    } else {
      // Fallback
      if (i > 0 && j > 0) {
        revOps.push({ op: "substitute", char: target[j - 1] });
        i--;
        j--;
      } else if (i > 0) {
        revOps.push({ op: "delete" });
        i--;
      } else {
        revOps.push({ op: "insert", char: target[j - 1] });
        j--;
      }
    }
  }

  revOps.reverse();

  return {
    editDistance,
    operations: revOps
  };
}

