  const m = source.length;
  const n = target.length;

  // Create DP matrix
  const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

  for (let i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (source[i - 1] === target[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        dp[i][j] = 1 + Math.min(
          dp[i - 1][j],    // deletion
          dp[i][j - 1],    // insertion
          dp[i - 1][j - 1] // substitution
        );
      }
    }
  }

  const editDistance = dp[m][n];

  // Backtrack to find operations
  let i = m;
  let j = n;
  const revOps = [];

  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && source[i - 1] === target[j - 1]) {
      // Check if this came from diagonal with no cost
      if (dp[i][j] === dp[i - 1][j - 1]) {
        revOps.push({ op: "keep", char: target[j - 1] });
        i--;
        j--;
        continue;
      }
    }

    let substitutions = [];
    if (i > 0 && j > 0) {
      substitutions.push({ val: dp[i - 1][j - 1], op: "substitute", i: i - 1, j: j - 1 });
    }
    let deletions = [];
    if (i > 0) {
      deletions.push({ val: dp[i - 1][j], op: "delete", i: i - 1, j: j });
    }
    let insertions = [];
    if (j > 0) {
      insertions.push({ val: dp[i][j - 1], op: "insert", i: i, j: j - 1 });
    }

    const currentVal = dp[i][j];

    // Find which transition led here
    let matched = false;

    // Priority: substitute/keep, delete, insert (standard backtracking order)
    if (i > 0 && j > 0 && dp[i - 1][j - 1] + (source[i - 1] === target[j - 1] ? 0 : 1) === currentVal) {
      if (source[i - 1] === target[j - 1]) {
        revOps.push({ op: "keep", char: target[j - 1] });
      } else {
        revOps.push({ op: "substitute", char: target[j - 1] });
      }
      i--;
      j--;
    } else if (i > 0 && dp[i - 1][j] + 1 === currentVal) {
      revOps.push({ op: "delete" });
      i--;
    } else if (j > 0 && dp[i][j - 1] + 1 === currentVal) {
      revOps.push({ op: "insert", char: target[j - 1] });
      j--;
    } else {
      // Fallback
      if (i > 0 && j > 0) {
        revOps.push({ op: "substitute", char: target[j - 1] });
        i--;
        j--;
      } else if (i > 0) {
        revOps.push({ op: "delete" });
        i--;
      } else {
        revOps.push({ op: "insert", char: target[j - 1] });
        j--;
      }
    }
  }

  revOps.reverse();

  return {
    editDistance,
    operations: revOps
  };
}

export default async function execute(args) {
  const { nodes, edges, start, end, turnPenalties } = args;

  const dirMap = { 'N': 0, 'E': 1, 'S': 2, 'W': 3 };

  function getTurnPenalty(inDir, outDir) {
    if (!inDir) return 0;
    const i1 = dirMap[inDir];
    const i2 = dirMap[outDir];
    const diff = (i2 - i1 + 4) % 4;
    let type = 'straight';
    if (diff === 1) type = 'right';
    else if (diff === 2) type = 'uTurn';
    else if (diff === 3) type = 'left';
    return turnPenalties[type];
  }

  // Build adjacency list
  const adj = {};
  for (const node of nodes) {
    adj[node] = [];
  }
  for (const edge of edges) {
    adj[edge.from].push(edge);
  }

  // Priority queue elements: { node, inDir, cost, path }
  // Since graph is small, we can use a simple array and sort/filter.
  let pq = [];

  // Initialize from start node
  for (const edge of adj[start]) {
    pq.push({
      node: edge.to,
      inDir: edge.direction,
      cost: edge.weight,
      path: [start, edge.to]
    });
  }

  // To avoid infinite loops or redundant states, keep visited map: key = `${node}|${inDir}` -> minCost
  const visited = {};

  while (pq.length > 0) {
    // Sort by cost ascending
    pq.sort((a, b) => a.cost - b.cost);
    const current = pq.shift();

    if (current.node === end) {
      return {
        path: current.path,
        totalCost: current.cost
      };
    }

    const stateKey = `${current.node}|${current.inDir}`;
    if (visited[stateKey] !== undefined && visited[stateKey] <= current.cost) {
      continue;
    }
    visited[stateKey] = current.cost;

    for (const edge of adj[current.node]) {
      const penalty = getTurnPenalty(current.inDir, edge.direction);
      const newCost = current.cost + edge.weight + penalty;
      const nextStateKey = `${edge.to}|${edge.direction}`;

      if (visited[nextStateKey] === undefined || newCost < visited[nextStateKey]) {
        pq.push({
          node: edge.to,
          inDir: edge.direction,
          cost: newCost,
          path: [...current.path, edge.to]
        });
      }
    }
  }

  return { path: [], totalCost: Infinity };
}

