  const { nodes, edges, start, end, turnPenalties } = args;

  // Map directions to indices
  const dirMap = { 'N': 0, 'E': 1, 'S': 2, 'W': 3 };

  // Build adjacency list
  const adj = {};
  for (const node of nodes) {
    adj[node] = [];
  }
  for (const edge of edges) {
    adj[edge.from].push({
      to: edge.to,
      weight: edge.weight,
      direction: edge.direction,
      dirIndex: dirMap[edge.direction]
    });
  }

  // Priority Queue implementation
  class MinPriorityQueue {
    constructor() {
      this.heap = [];
    }
    push(item) {
      this.heap.push(item);
      this.up(this.heap.length - 1);
    }
    pop() {
      if (this.heap.length === 0) return null;
      const top = this.heap[0];
      const bottom = this.heap.pop();
      if (this.heap.length > 0) {
        this.heap[0] = bottom;
        this.down(0);
      }
      return top;
    }
    size() {
      return this.heap.length;
    }
    up(i) {
      while (i > 0) {
        const p = Math.floor((i - 1) / 2);
        if (this.heap[p].cost > this.heap[i].cost) {
          [this.heap[p], this.heap[i]] = [this.heap[i], this.heap[p]];
          i = p;
        } else {
          break;
        }
      }
    }
    down(i) {
      const len = this.heap.length;
      while (true) {
        let left = 2 * i + 1;
        let right = 2 * i + 2;
        let smallest = i;

        if (left < len && this.heap[left].cost < this.heap[smallest].cost) {
          smallest = left;
        }
        if (right < len && this.heap[right].cost < this.heap[smallest].cost) {
          smallest = right;
        }
        if (smallest !== i) {
          [this.heap[i], this.heap[smallest]] = [this.heap[smallest], this.heap[i]];
          i = smallest;
        } else {
          break;
        }
      }
    }
  }

  const pq = new MinPriorityQueue();
  // State: cost, node, dirIndex (null for start), path
  pq.push({ cost: 0, node: start, dirIndex: null, path: [start] });

  // Best cost memoization: best[node][dirIndex] = cost
  const best = {};
