  adj[start].forEach(edge => {
    pq.push({
      cost: edge.weight,
      node: edge.to,
      dir: edge.dir,
      path: [start, edge.to]
    });
  });

  // To avoid redundant states, keep track of min cost for (node, dir)
  const visitedMinCost = {};

  let bestResult = null;

  while (pq.length > 0) {
    // Sort to get the minimum cost element
    pq.sort((a, b) => a.cost - b.cost);
    const current = pq.shift();

    if (current.node === end) {
      bestResult = { path: current.path, totalCost: current.cost };
      break;
    }

    const stateKey = `${current.node}_${current.dir}`;
    if (visitedMinCost[stateKey] !== undefined && visitedMinCost[stateKey] <= current.cost) {
      continue;
    }
    visitedMinCost[stateKey] = current.cost;

    // Explore neighbors
    const neighbors = adj[current.node] || [];
    for (const neighbor of neighbors) {
