      const newCost = current.cost + neighbor.weight + penalty;
      const newPath = [...current.path, neighbor.to];

      pq.push({
        cost: newCost,
        node: neighbor.to,
        dir: neighbor.dir,
        path: newPath
      });
    }
  }

