/**
 * Executes a 2D pivot table aggregation on exam records.
 * @param {Object} args - Task input arguments.
 * @param {string} args.csv - CSV string containing the data.
 * @param {string} args.rowField - Field to group by rows (e.g., 'Subject').
 * @param {string} args.colField - Field to group by columns (e.g., 'GradeLevel').
 * @param {string} args.sumField - Field to sum (e.g., 'Credits').
 * @param {string} args.avgField - Field to average (e.g., 'Score').
 * @returns {Promise<Object>} - The pivot table result as JSON.
 */
export default async function execute(args) {
  const { csv, rowField, colField, sumField, avgField } = args;

  // Parse CSV
  const lines = csv.trim().split('\n');
  if (lines.length === 0) return {};

  const headers = lines[0].split(',').map(h => h.trim());
  const rows = lines.slice(1).map(line => {
    const values = line.split(',');
    const obj = {};
    headers.forEach((h, index) => {
      obj[h] = values[index] ? values[index].trim() : '';
    });
    return obj;
  });

  // Aggregation structure: { [rowVal]: { [colVal]: { sum: number, count: number, scoreSum: number } } }
  const pivot = {};

  for (const row of rows) {
    const rowKey = row[rowField];
    const colKey = row[colField];
    const sumVal = parseFloat(row[sumField]) || 0;
    const avgVal = parseFloat(row[avgField]) || 0;

    if (!rowKey || !colKey) continue;

    if (!pivot[rowKey]) {
      pivot[rowKey] = {};
    }

    if (!pivot[rowKey][colKey]) {
      pivot[rowKey][colKey] = {
        sum: 0,
        scoreSum: 0,
        count: 0
      };
    }

    pivot[rowKey][colKey].sum += sumVal;
    pivot[rowKey][colKey].scoreSum += avgVal;
    pivot[rowKey][colKey].count += 1;
  }

  // Format output: { [rowKey]: { [colKey]: { "sum": number, "avg": number } } }
  const result = {};

  for (const rowKey of Object.keys(pivot)) {
    result[rowKey] = {};
    for (const colKey of Object.keys(pivot[rowKey])) {
      const data = pivot[rowKey][colKey];
      const avg = data.count > 0 ? Number((data.scoreSum / data.count).toFixed(2)) : 0;
      result[rowKey][colKey] = {
        sum: data.sum,
        avg: avg
      };
    }
  }

  return result;
}

export default async function execute(args) {
