export default async function execute(args) {
  const { source, target } = args;

  const m = source.length;
  const n = target.length;

  // Initialize DP matrix with dimensions (m + 1) x (n + 1)
  const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

  for (let i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (source[i - 1] === target[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        dp[i][j] = Math.min(
          dp[i - 1][j] + 1,     // deletion
          dp[i][j - 1] + 1,     // insertion
          dp[i - 1][j - 1] + 1  // substitution
        );
      }
    }
  }

  const editDistance = dp[m][n];

  // Backtrack to find operations
  let i = m;
  let j = n;
  const reverseOps = [];

  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && source[i - 1] === target[j - 1] && dp[i][j] === dp[i - 1][j - 1]) {
      reverseOps.push({ op: "keep" });
      i--;
      j--;
    } else {
      let substituted = false;
      let inserted = false;
      let deleted = false;

      // Check substitution first or prioritize based on min values
      const currentVal = dp[i][j];

      if (i > 0 && j > 0 && dp[i - 1][j - 1] + 1 === currentVal) {
        reverseOps.push({ op: "substitute", char: target[j - 1] });
        i--;
        j--;
        substituted = true;
      } else if (j > 0 && dp[i][j - 1] + 1 === currentVal) {
        reverseOps.push({ op: "insert", char: target[j - 1] });
        j--;
        inserted = true;
      } else if (i > 0 && dp[i - 1][j] + 1 === currentVal) {
        reverseOps.push({ op: "delete" });
        i--;
        deleted = true;
      } else {
        // Fallback safety to prevent infinite loops
        if (i > 0 && j > 0) {
          reverseOps.push({ op: "substitute", char: target[j - 1] });
          i--;
          j--;
        } else if (j > 0) {
          reverseOps.push({ op: "insert", char: target[j - 1] });
          j--;
        } else if (i > 0) {
          reverseOps.push({ op: "delete" });
          i--;
        }
      }
    }
  }

  reverseOps.reverse();

  return {
    editDistance,
    operations: reverseOps
  };
