  nodes.forEach(n => { adj[n] = []; });
  edges.forEach(e => {
    adj[e.from].push({
      to: e.to,
      weight: e.weight,
      dir: dirMap[e.direction]
    });
  });

  // Priority queue element: { node, dir, cost, path }
  // Since we need to avoid while(true), we can use a simple array-based priority queue with a max iteration safety bound.
  const pq = [];

  // Initial state: start node has no incoming direction yet. We can push all outgoing edges from start.
  // Or we push start with dir = null, cost = 0.
  pq.push({ node: start, dir: null, cost: 0, path: [start] });

  const visited = {}; // key: node + "_" + dir -> min cost

  let bestResult = { path: null, totalCost: Infinity };

  let iterations = 0;
  const maxIterations = 10000;

  while (pq.length > 0 && iterations < maxIterations) {
    iterations++;

    // Find min cost item
    let minIdx = 0;
    for (let i = 1; i < pq.length; i++) {
      if (pq[i].cost < pq[minIdx].cost) {
        minIdx = i;
      }
    }

    const current = pq.splice(minIdx, 1)[0];
    const { node, dir, cost, path } = current;

    if (node === end) {
      if (cost < bestResult.totalCost) {
        bestResult = { path, totalCost: cost };
      }
      continue;
    }

    const stateKey = node + "_" + (dir === null ? "null" : dir);
    if (visited[stateKey] !== undefined && visited[stateKey] < cost) {
      continue;
    }
