export default async function execute(args) {
  const { nodes, edges, start, end, turnPenalties } = args;

  const adj = {};
  nodes.forEach(n => {
    adj[n] = [];
  });
  edges.forEach(e => {
    adj[e.from].push({ to: e.to, weight: e.weight, direction: e.direction });
  });

  const dirs = ['N', 'E', 'S', 'W'];
  function getTurnCost(prevDir, currDir) {
    if (!prevDir) return 0;
    const i1 = dirs.indexOf(prevDir);
    const i2 = dirs.indexOf(currDir);
    const diff = (i2 - i1 + 4) % 4;
    if (diff === 0) return turnPenalties.straight;
    if (diff === 1) return turnPenalties.right;
    if (diff === 2) return turnPenalties.uTurn;
    if (diff === 3) return turnPenalties.left;
    return 0;
  }

  let pq = [{ cost: 0, node: start, dir: null, path: [start] }];
  const visited = new Set();

  while (pq.length > 0) {
    pq.sort((a, b) => a.cost - b.cost);
    const curr = pq.shift();

    if (curr.node === end) {
      return {
        path: curr.path,
        totalCost: curr.cost
      };
    }

    const stateKey = `${curr.node}|${curr.dir || 'NONE'}`;
    if (visited.has(stateKey)) continue;
    visited.add(stateKey);

    for (const edge of adj[curr.node] || []) {
      const turnCost = getTurnCost(curr.dir, edge.direction);
      const newCost = curr.cost + edge.weight + turnCost;
      const nextStateKey = `${edge.to}|${edge.direction}`;

      if (!visited.has(nextStateKey)) {
        pq.push({
          cost: newCost,
          node: edge.to,
          dir: edge.direction,
          path: [...curr.path, edge.to]
        });
      }
    }
  }

  return { path: [], totalCost: Infinity };
}

export default async function execute(args) {
  const { csv, rowField, colField, sumField, avgField } = args;

  // Simple CSV parser supporting standard rows and columns
  const lines = csv.trim().split('\n');
  if (lines.length === 0) return {};

  const headers = lines[0].split(',').map(h => h.trim());

  const rowIndex = headers.indexOf(rowField);
  const colIndex = headers.indexOf(colField);
  const sumIndex = headers.indexOf(sumField);
  const avgIndex = headers.indexOf(avgField);

  // Intermediate structure to store totals and counts
  // { [region]: { [quarter]: { sum: number, sumMargin: number, count: number } } }
  const pivot = {};

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    // Naive CSV split, adequate for this structure (no quoted commas)
    const cols = line.split(',').map(c => c.trim());

    const rowVal = cols[rowIndex];
    const colVal = cols[colIndex];
    const sumVal = parseFloat(cols[sumIndex]);
    const avgVal = parseFloat(cols[avgIndex]);

    if (!pivot[rowVal]) {
      pivot[rowVal] = {};
    }

    if (!pivot[rowVal][colVal]) {
      pivot[rowVal][colVal] = {
        sum: 0,
        sumMargin: 0,
        count: 0
      };
    }

    pivot[rowVal][colVal].sum += sumVal;
    pivot[rowVal][colVal].sumMargin += avgVal;
    pivot[rowVal][colVal].count += 1;
  }

  // Format final output
  const result = {};
  for (const rowVal of Object.keys(pivot)) {
    result[rowVal] = {};
    for (const colVal of Object.keys(pivot[rowVal])) {
      const cell = pivot[rowVal][colVal];
      const avg = cell.count > 0 ? Number((cell.sumMargin / cell.count).toFixed(2)) : 0;
      result[rowVal][colVal] = {
        sum: cell.sum,
        avg: avg
      };
    }
  }

  return result;
}

