 * @param {string} args.rowField
 * @param {string} args.colField
 * @param {string} args.sumField
 * @param {string} args.avgField
 * @returns {Promise<Object>}
 */
export default async function execute(args) {
  const { csv, rowField, colField, sumField, avgField } = args;

  const lines = csv.trim().split(/\r?\n/);
  if (lines.length === 0) return {};

  const headers = lines[0].split(',').map(h => h.trim());

  const rowIndex = headers.indexOf(rowField);
  const colIndex = headers.indexOf(colField);
  const sumIndex = headers.indexOf(sumField);
  const avgIndex = headers.indexOf(avgField);

  if (rowIndex === -1 || colIndex === -1 || sumIndex === -1 || avgIndex === -1) {
    throw new Error('One or more specified fields not found in CSV headers.');
  }

  // Intermediate storage: { [cluster]: { [tier]: { sum: number, count: number, totalLatency: number } } }
  const aggregation = {};

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    const cols = line.split(',');
    const rowVal = cols[rowIndex].trim();
    const colVal = cols[colIndex].trim();
    const sumVal = parseFloat(cols[sumIndex]);
    const avgVal = parseFloat(cols[avgIndex]);

    if (!aggregation[rowVal]) {
      aggregation[rowVal] = {};
    }

    if (!aggregation[rowVal][colVal]) {
      aggregation[rowVal][colVal] = {
        sum: 0,
        count: 0,
        totalLatency: 0
      };
    }

    aggregation[rowVal][colVal].sum += sumVal;
    aggregation[rowVal][colVal].count += 1;
    aggregation[rowVal][colVal].totalLatency += avgVal;
  }

  // Format final output
  const result = {};
  for (const cluster of Object.keys(aggregation)) {
    result[cluster] = {};
    for (const tier of Object.keys(aggregation[cluster])) {
      const data = aggregation[cluster][tier];
      const avg = data.count > 0 ? Number((data.totalLatency / data.count).toFixed(2)) : 0;
      result[cluster][tier] = {
        sum: data.sum,
        avg: avg
      };
    }
  }

