    // Pivot table structure: { [row]: { [col]: { sum: number, count: number, scoreSum: number } } }
    const pivot = {};

    for (const rec of records) {
        const rowVal = rec[rowField];
        const colVal = rec[colField];
        const sumVal = Number(rec[sumField]) || 0;
        const avgVal = Number(rec[avgField]) || 0;

        if (!pivot[rowVal]) {
            pivot[rowVal] = {};
        }
        if (!pivot[rowVal][colVal]) {
            pivot[rowVal][colVal] = {
                sum: 0,
                scoreSum: 0,
                count: 0
            };
        }

        pivot[rowVal][colVal].sum += sumVal;
        pivot[rowVal][colVal].scoreSum += avgVal;
        pivot[rowVal][colVal].count += 1;
    }

    // Format output
    const result = {};
    for (const rowVal of Object.keys(pivot)) {
        result[rowVal] = {};
        for (const colVal of Object.keys(pivot[rowVal])) {
            const cell = pivot[rowVal][colVal];
            const avg = cell.count > 0 ? Number((cell.scoreSum / cell.count).toFixed(2)) : 0;
            result[rowVal][colVal] = {
                sum: cell.sum,
                avg: avg
            };
        }
    }

    return result;
}

/**
 * Executes the 0/1 Knapsack problem with dual capacity constraints (maxWeight and maxVolume).
 * 
 * @param {Object} args - Task input containing items, maxWeight, and maxVolume.
 * @returns {Promise<Object>} - Resolves with { selectedIds: number[], totalValue: number }
 */
export default async function execute(args) {
  const { items, maxWeight, maxVolume } = args;

  let bestValue = -1;
  let bestCombination = [];

  function search(index, currentWeight, currentVolume, currentValue, currentIds) {
    if (currentValue > bestValue) {
      bestValue = currentValue;
      bestCombination = [...currentIds];
    }

    if (index >= items.length) {
      return;
    }

    // Branch 1: Skip current item
    search(index + 1, currentWeight, currentVolume, currentValue, currentIds);

    // Branch 2: Take current item (if it fits)
    const item = items[index];
    if (currentWeight + item.weight <= maxWeight && currentVolume + item.volume <= maxVolume) {
      currentIds.push(item.id);
      search(index + 1, currentWeight + item.weight, currentVolume + item.volume, currentValue + item.value, currentIds);
      currentIds.pop();
    }
  }

  search(0, 0, 0, 0, []);

  // Sort IDs for neatness
  bestCombination.sort((a, b) => a - b);

  return {
    selectedIds: bestCombination,
    totalValue: bestValue
  };
}

