export default async function execute(args) {
  const { markdown } = args;

  // Split into lines and filter out empty ones
  const lines = markdown
    .trim()
    .split('\n')
    .map(l => l.trim())
    .filter(Boolean);

  if (lines.length < 2) {
    return [];
  }

  // Helper function to parse a markdown table row into cells, handling escaped pipes
  const parseRow = (line) => {
    let cleanLine = line;
    if (cleanLine.startsWith('|')) {
      cleanLine = cleanLine.slice(1);
    }
    if (cleanLine.endsWith('|')) {
      cleanLine = cleanLine.slice(0, -1);
    }

    // Replace escaped pipes (\|) with a temporary unique placeholder
    const PLACEHOLDER = '\uFFFF';
    const unescaped = cleanLine.replace(/\\\|/g, PLACEHOLDER);

    return unescaped.split('|').map(cell => {
      let val = cell.trim().replace(new RegExp(PLACEHOLDER, 'g'), '|');

      // Parse booleans
      if (val.toLowerCase() === 'true') {
        return true;
      }
      if (val.toLowerCase() === 'false') {
        return false;
      }

      // Parse numbers
      if (val !== '' && !isNaN(Number(val))) {
        return Number(val);
      }

      return val;
    });
  };

  // First line is headers
  const headers = parseRow(lines[0]);

  // Second line is the markdown alignment separator (e.g., | :--- | :---: |), skip it
  const dataRows = lines.slice(2);

  // Map each data row to an object using headers as keys
  const result = dataRows.map(line => {
    const values = parseRow(line);
    const obj = {};
    headers.forEach((header, index) => {
      obj[header] = values[index] !== undefined ? values[index] : '';
    });
    return obj;
  });

  return result;
}

