/**
 * Parses a markdown table into an array of JSON objects.
 * Columns become keys, edge pipes are stripped, whitespace trimmed,
 * escaped pipes (\|) become literal '|', and booleans/numbers are properly typed.
 * 
 * @param {object} args - The task arguments containing the markdown string.
 * @param {string} args.markdown - The markdown table text.
 * @returns {Promise<Array<object>>} - The array of parsed objects.
 */
export default async function execute(args) {
  const { markdown } = args;
  if (!markdown) return [];

  const lines = markdown
    .trim()
    .split('\n')
    .map(line => line.trim())
    .filter(line => line.length > 0);

  if (lines.length < 2) return [];

  // Helper to split a table row by unescaped pipes
  function parseRow(rowStr) {
    // Remove leading and trailing pipes if present
    let content = rowStr;
    if (content.startsWith('|')) {
      content = content.slice(1);
    }
    if (content.endsWith('|')) {
      content = content.slice(0, -1);
    }

    const cells = [];
    let currentCell = '';
    let escaped = false;

    for (let i = 0; i < content.length; i++) {
      const char = content[i];
      if (escaped) {
        if (char === '|') {
          currentCell += '|';
        } else {
          currentCell += '\\' + char;
        }
        escaped = false;
      } else if (char === '\\') {
        escaped = true;
      } else if (char === '|') {
        cells.push(currentCell.trim());
        currentCell = '';
      } else {
        currentCell += char;
      }
    }
    cells.push(currentCell.trim());
    return cells;
  }

  // Helper to typecast values
  function parseValue(val) {
    if (val.toLowerCase() === 'true') return true;
    if (val.toLowerCase() === 'false') return false;

    // Check if it's a number
    if (val !== '' && !isNaN(Number(val))) {
      return Number(val);
    }

    return val;
  }

  const headers = parseRow(lines[0]);
  // lines[1] is the delimiter row, skip it
  const dataLines = lines.slice(2);

  const result = dataLines.map(line => {
    const cells = parseRow(line);
    const obj = {};
    headers.forEach((header, index) => {
      const rawVal = cells[index] !== undefined ? cells[index] : '';
      obj[header] = parseValue(rawVal);
    });
    return obj;
  });

  return result;
}

