/**
 * Computes the optimal Levenshtein edit distance and operation alignment script
 * transforming the source DNA string into the target DNA string.
 * 
 * @param {Object} args - Task input containing source and target strings.
 * @param {string} args.source - Source DNA string.
 * @param {string} args.target - Target DNA string.
 * @returns {Promise<Object>} Object containing editDistance and operations array.
 */
export default async function execute(args) {
  const { source, target } = args;
  const m = source.length;
  const n = target.length;

  // DP table of size (m + 1) x (n + 1)
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));

  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;

  for (let i = 1; i <= m; i++) {
    const charS = source[i - 1];
    for (let j = 1; j <= n; j++) {
      const charT = target[j - 1];
      if (charS === charT) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        const deletion = dp[i - 1][j] + 1;
        const insertion = dp[i][j - 1] + 1;
        const substitution = dp[i - 1][j - 1] + 1;
        dp[i][j] = Math.min(deletion, insertion, substitution);
      }
    }
  }

  const editDistance = dp[m][n];

  // Backtrack to find the operations
  let i = m;
  let j = n;
  const revOps = [];

  while (i > 0 || j > 0) {
    const charS = i > 0 ? source[i - 1] : null;
    const charT = j > 0 ? target[j - 1] : null;

    if (i > 0 && j > 0 && charS === charT && dp[i][j] === dp[i - 1][j - 1]) {
      revOps.push({ op: 'keep', char: charS });
      i--;
      j--;
    } else {
      let currentVal = dp[i][j];

      // Check substitution
      if (i > 0 && j > 0 && currentVal === dp[i - 1][j - 1] + 1) {
        revOps.push({ op: 'substitute', from: charS, to: charT });
        i--;
        j--;
      } 
      // Check deletion (source char deleted)
      else if (i > 0 && currentVal === dp[i - 1][j] + 1) {
        revOps.push({ op: 'delete', char: charS });
        i--;
      } 
      // Check insertion (target char inserted)
      else if (j > 0 && currentVal === dp[i][j - 1] + 1) {
        revOps.push({ op: 'insert', char: charT });
        j--;
      }
    }
  }

  revOps.reverse();

  return {
    editDistance,
    operations: revOps
  };
}

