export default async function execute(args) {
  const { nodes, edges, start, end, turnPenalties } = args;

  const dirMap = { N: 0, E: 1, S: 2, W: 3 };

  function getTurnType(inDir, outDir) {
    if (inDir === null) return 'straight';
    const diff = (dirMap[outDir] - dirMap[inDir] + 4) % 4;
    if (diff === 0) return 'straight';
    if (diff === 1) return 'right';
    if (diff === 2) return 'uTurn';
    if (diff === 3) return 'left';
    return 'straight';
  }

  // Build adjacency list: node -> array of { to, weight, direction }
  const adj = {};
  for (const node of nodes) {
    adj[node] = [];
  }
  for (const edge of edges) {
    adj[edge.from].push(edge);
  }

  // Priority queue elements: { cost, node, dir, path }
  // Since we want shortest path, let's use a simple array-based priority queue or sorted array.
  let pq = [];

  // For start node, we can initiate with each outgoing edge with no turn penalty.
  for (const edge of adj[start]) {
    pq.push({
      cost: edge.weight,
      node: edge.to,
      dir: edge.direction,
      path: [start, edge.to]
    });
  }

  // To avoid redundant visits, keep visited min costs for state: key = `${node}_${dir}`
  const visited = {};

  while (pq.length > 0) {
    // Sort pq by cost ascending (simple implementation, fine for small graphs)
    pq.sort((a, b) => a.cost - b.cost);
    const current = pq.shift();

    if (current.node === end) {
      return {
        path: current.path,
        totalCost: current.cost
      };
    }

    const stateKey = `${current.node}_${current.dir}`;
    if (visited[stateKey] !== undefined && visited[stateKey] <= current.cost) {
      continue;
    }
    visited[stateKey] = current.cost;

    for (const edge of adj[current.node]) {
      const turnType = getTurnType(current.dir, edge.direction);
      const penalty = turnPenalties[turnType];
      const newCost = current.cost + edge.weight + penalty;
      const newStateKey = `${edge.to}_${edge.direction}`;

      if (visited[newStateKey] === undefined || newCost < visited[newStateKey]) {
        pq.push({
          cost: newCost,
          node: edge.to,
          dir: edge.direction,
          path: [...current.path, edge.to]
        });
      }
    }
  }

  return { path: [], totalCost: Infinity };
}

