export default async function execute(args) {
  const { nodes, edges, start, end, turnPenalties } = args;

  // Map direction to index
  const dirMap = { N: 0, E: 1, S: 2, W: 3 };

  function getTurnType(dir1, dir2) {
    if (!dir1) return 'straight';
    const d1 = dirMap[dir1];
    const d2 = dirMap[dir2];
    const diff = (d2 - d1 + 4) % 4;
    if (diff === 0) return 'straight';
    if (diff === 1) return 'right';
    if (diff === 3) return 'left';
    return 'uTurn';
  }

  // Build adjacency list: node -> array of { to, weight, direction }
  const adj = {};
  for (const node of nodes) {
    adj[node] = [];
  }
  for (const edge of edges) {
    adj[edge.from].push({
      to: edge.to,
      weight: edge.weight,
      direction: edge.direction
    });
  }

  // Dijkstra state: key = `${node},${dir}`
  // Priority queue: array of { cost, node, dir, path }
  const pq = [{
    cost: 0,
    node: start,
    dir: null,
    path: [start]
  }];

  const visited = new Set();
  let bestResult = null;

  while (pq.length > 0) {
    // Sort to simulate min-heap
    pq.sort((a, b) => a.cost - b.cost);
    const curr = pq.shift();

    const stateKey = `${curr.node},${curr.dir}`;
    if (visited.has(stateKey)) continue;
    visited.add(stateKey);

    if (curr.node === end) {
      bestResult = {
        path: curr.path,
        totalCost: curr.cost
      };
      break;
    }

    for (const neighbor of adj[curr.node]) {
      const turnType = getTurnType(curr.dir, neighbor.direction);
      const penalty = turnPenalties[turnType] || 0;
      const newCost = curr.cost + neighbor.weight + penalty;
      const nextStateKey = `${neighbor.to},${neighbor.direction}`;

      if (!visited.has(nextStateKey)) {
        pq.push({
          cost: newCost,
          node: neighbor.to,
          dir: neighbor.direction,
          path: [...curr.path, neighbor.to]
        });
      }
    }
  }

  return bestResult;
}

