export default async function execute(args) {
  const { csv, rowField, colField, sumField, avgField } = args;

  // Simple CSV parser supporting standard rows
  const lines = csv.trim().split('\n');
  if (lines.length === 0) return {};

  const headers = lines[0].split(',').map(h => h.trim());

  const rowIndex = headers.indexOf(rowField);
  const colIndex = headers.indexOf(colField);
  const sumIndex = headers.indexOf(sumField);
  const avgIndex = headers.indexOf(avgField);

  // Structure to hold raw sums and counts for aggregation
  // { [region]: { [quarter]: { sum: number, count: number, totalMargin: number } } }
  const aggregation = {};

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    // Naive split, assuming no quoted commas in this simple context
    const cols = line.split(',').map(c => c.trim());

    const rowVal = cols[rowIndex];
    const colVal = cols[colIndex];
    const sumVal = parseFloat(cols[sumIndex]);
    const avgVal = parseFloat(cols[avgIndex]);

    if (!aggregation[rowVal]) {
      aggregation[rowVal] = {};
    }

    if (!aggregation[rowVal][colVal]) {
      aggregation[rowVal][colVal] = {
        sum: 0,
        totalMargin: 0,
        count: 0
      };
    }

    aggregation[rowVal][colVal].sum += sumVal;
    aggregation[rowVal][colVal].totalMargin += avgVal;
    aggregation[rowVal][colVal].count += 1;
  }

  // Format to requested output: { [region]: { [quarter]: { "sum": number, "avg": number } } }
  const result = {};

  for (const [region, quarters] of Object.entries(aggregation)) {
    result[region] = {};
    for (const [quarter, data] of Object.entries(quarters)) {
      const avg = data.count > 0 ? data.totalMargin / data.count : 0;
      result[region][quarter] = {
        sum: data.sum,
        avg: Math.round(avg * 100) / 100
      };
    }
  }

  return result;
}

