/**
 * Executes a 2D pivot table aggregation on server telemetry logs.
 * @param {Object} args - The input arguments.
 * @param {string} args.csv - The CSV string containing the telemetry logs.
 * @param {string} args.rowField - The field name to group by as rows.
 * @param {string} args.colField - The field name to group by as columns.
 * @param {string} args.sumField - The numeric field to aggregate by sum.
 * @param {string} args.avgField - The numeric field to aggregate by average.
 * @returns {Promise<Object>} The aggregated pivot table as a nested JSON object.
 */
export default async function execute(args) {
  const { csv, rowField, colField, sumField, avgField } = args;

  const lines = csv.trim().split('\n');
  if (lines.length === 0) return {};

  const headers = lines[0].split(',').map(h => h.trim());

  const rowIndex = headers.indexOf(rowField);
  const colIndex = headers.indexOf(colField);
  const sumIndex = headers.indexOf(sumField);
  const avgIndex = headers.indexOf(avgField);

  // Intermediate structure to hold sum and count for averages, and sum for totals
  // { [rowVal]: { [colVal]: { sumRequests: number, sumLatency: number, countLatency: number } } }
  const pivotData = {};

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    // Simple CSV split (assuming no quoted commas in this schema)
    const cols = line.split(',').map(c => c.trim());

    const rowVal = cols[rowIndex];
    const colVal = cols[colIndex];
    const sumVal = parseFloat(cols[sumIndex]);
    const avgVal = parseFloat(cols[avgIndex]);

    if (!pivotData[rowVal]) {
      pivotData[rowVal] = {};
    }

    if (!pivotData[rowVal][colVal]) {
      pivotData[rowVal][colVal] = {
        sum: 0,
        latencySum: 0,
        latencyCount: 0
      };
    }

    pivotData[rowVal][colVal].sum += sumVal;
    pivotData[rowVal][colVal].latencySum += avgVal;
    pivotData[rowVal][colVal].latencyCount += 1;
  }

  // Format the output structure
  const result = {};

  for (const rowVal of Object.keys(pivotData)) {
    result[rowVal] = {};
    for (const colVal of Object.keys(pivotData[rowVal])) {
      const cell = pivotData[rowVal][colVal];
      const avg = cell.latencyCount > 0 ? cell.latencySum / cell.latencyCount : 0;

      result[rowVal][colVal] = {
        sum: cell.sum,
        avg: Number(avg.toFixed(2))
      };
    }
  }

  return result;
}

