    for (const colVal of Object.keys(pivot[rowVal])) {
      const data = pivot[rowVal][colVal];
      const avg = data.count > 0 ? Number((data.scoreSum / data.count).toFixed(2)) : 0;

      result[rowVal][colVal] = {
        sum: data.sum,
        avg: avg
      };
    }
  }

  return result;
}

export default async function execute(args) {
  const { items, maxWeight, maxVolume } = args;
  const n = items.length;

  // 3D DP table: dp[i][w][v]
  // Since capacities are relatively small (maxWeight=35, maxVolume=45), we can use a 3D array or memoized recursion/iterative DP.
  // Actually, to save memory and ensure speed, an iterative 2D array for weight and volume is standard:
  // dp[w][v] = max value with weight <= w and volume <= v.

  // Initialize 2D DP table: (maxWeight + 1) x (maxVolume + 1)
  const dp = Array.from({ length: maxWeight + 1 }, () => 
    new Int32Array(maxVolume + 1)
  );

  // To reconstruct the solution, we can store choices or a 3D boolean array indicating item inclusion.
  // kept[i][w][v] = true if item i was included
  const kept = Array.from({ length: n + 1 }, () => 
    Array.from({ length: maxWeight + 1 }, () => 
      new Uint8Array(maxVolume + 1)
    )
  );

  for (let i = 0; i < n; i++) {
    const item = items[i];
    const { id, value, weight, volume } = item;

    // Iterate backwards to use 0/1 knapsack approach
    for (let w = maxWeight; w >= weight; w--) {
      for (let v = maxVolume; v >= volume; v--) {
        const prevVal = dp[w - weight][v - volume];
        const newVal = prevVal + value;
        if (newVal > dp[w][v]) {
          dp[w][v] = newVal;
          kept[i + 1][w][v] = 1;
        }
      }
    }
  }

  // Find the max value and its coordinates
  let maxVal = 0;
  let bestW = 0;
  let bestV = 0;

  for (let w = 0; w <= maxWeight; w++) {
    for (let v = 0; v <= maxVolume; v++) {
      if (dp[w][v] > maxVal) {
        maxVal = dp[w][v];
        bestW = w;
        bestV = v;
      }
    }
  }

  // Reconstruct path
  const selectedIds = [];
  let currW = bestW;
  let currV = bestV;

  for (let i = n; i >= 1; i--) {
    if (kept[i][currW][currV]) {
      const item = items[i - 1];
      selectedIds.push(item.id);
      currW -= item.weight;
      currV -= item.volume;
    }
  }

  selectedIds.sort((a, b) => a - b);

  return {
    selectedIds,
    totalValue: maxVal
  };
}

