/**
 * Executes the satellite instrument selection optimization (2D Knapsack Problem).
 * @param {Object} args - Task input arguments.
 * @param {Array} args.items - List of items with id, value, weight, volume.
 * @param {number} args.maxWeight - Maximum allowed weight limit.
 * @param {number} args.maxVolume - Maximum allowed volume limit.
 * @returns {Promise<{selectedIds: number[], totalValue: number}>}
 */
export default async function execute(args) {
  const { items, maxWeight, maxVolume } = args;

  let bestValue = -1;
  let bestCombination = [];

  const n = items.length;
  const totalCombos = 1 << n;

  for (let i = 0; i < totalCombos; i++) {
    let currentWeight = 0;
    let currentVolume = 0;
    let currentValue = 0;
    let currentIds = [];

    for (let j = 0; j < n; j++) {
      if ((i & (1 << j)) !== 0) {
        const item = items[j];
        currentWeight += item.weight;
        currentVolume += item.volume;
        currentValue += item.value;
        currentIds.push(item.id);
      }
    }

    if (currentWeight <= maxWeight && currentVolume <= maxVolume) {
      if (currentValue > bestValue) {
        bestValue = currentValue;
        bestCombination = currentIds;
      }
    }
  }

  return {
    selectedIds: bestCombination.sort((a, b) => a - b),
    totalValue: bestValue === -1 ? 0 : bestValue
  };
}

